import { createContext, useCallback, useContext, useState, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { liveAnnouncerVariants } from './live-announcer.variants';

export type AnnouncePoliteness = 'polite' | 'assertive';
/** Sends a message to the nearest LiveAnnouncer region. */
export type Announce = (message: string, politeness?: AnnouncePoliteness) => void;

const AnnounceContext = createContext<Announce | null>(null);
const noop: Announce = () => {};

export interface LiveAnnouncerProps {
  children?: ReactNode;
  /** Classes for the (screen-reader only) region. */
  className?: string;
}

/**
 * Screen-reader announcements for interactions that have no visible text change (drag and drop,
 * reorder, background saves). Renders polite and assertive `aria-live` regions and gives its
 * subtree `useAnnounce()`. Repeating the same message re-announces it.
 */
export function LiveAnnouncer({ children, className }: LiveAnnouncerProps) {
  const [polite, setPolite] = useState('');
  const [assertive, setAssertive] = useState('');
  const announce = useCallback<Announce>((message, politeness = 'polite') => {
    // A trailing no-break space makes an identical message a DOM change, so it is read again.
    const next = (prev: string) => (prev === message ? `${message}\u00A0` : message);
    if (politeness === 'assertive') setAssertive(next);
    else setPolite(next);
  }, []);
  const region = cn(liveAnnouncerVariants(), className);
  return (
    <AnnounceContext.Provider value={announce}>
      {children}
      <div role="status" aria-live="polite" aria-atomic="true" className={region} data-live-announcer="polite">
        {polite}
      </div>
      <div aria-live="assertive" aria-atomic="true" className={region} data-live-announcer="assertive">
        {assertive}
      </div>
    </AnnounceContext.Provider>
  );
}

/**
 * The `announce(message, politeness?)` function of the nearest LiveAnnouncer. Outside one it is
 * a no-op, so components can call it unconditionally.
 */
export function useAnnounce(): Announce {
  return useContext(AnnounceContext) ?? noop;
}

/** True when a LiveAnnouncer is already above this component (so it need not render its own). */
export function useHasLiveAnnouncer(): boolean {
  return useContext(AnnounceContext) !== null;
}

export { LiveAnnouncer, useAnnounce, useHasLiveAnnouncer, type LiveAnnouncerProps, type Announce, type AnnouncePoliteness } from './LiveAnnouncer';
export { liveAnnouncerVariants, type LiveAnnouncerVariantProps } from './live-announcer.variants';
export { doc as liveAnnouncerDoc } from './LiveAnnouncer.doc';

import { tv, type VariantProps } from '../../utils/tv';

/** The announcer region is screen-reader only; it never takes space or colour. */
export const liveAnnouncerVariants = tv({
  base: 'sr-only',
});

export type LiveAnnouncerVariantProps = VariantProps<typeof liveAnnouncerVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'LiveAnnouncer',
  group: 'Feedback',
  status: 'beta',
  description:
    'Screen-reader announcements for changes with no visible text: a polite (role="status") and an assertive aria-live region, plus `useAnnounce()` for any component below it. Used by KanbanBoard for pick-up / move / drop / cancel. Outside a LiveAnnouncer, `useAnnounce()` is a no-op.',
  pattern: 'aria-live region (status)',
  tokens: [],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
